cd "maintenance/inputs/provider-s03/migration-requests" && /c/Python314/python - <<'EOF'
import re, json, csv

def parse_md(path):
    records = {}
    pat = re.compile(r'\*\*(provider-s03-t04-\d{6})\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \| Evidence: (.*)$')
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = pat.search(line.strip())
            if m:
                records[m.group(1)] = {"system": m.group(2), "status": m.group(3), "note": m.group(4).rstrip()}
    return records

def parse_jsonl(path):
    records = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            records[obj["case"]] = {"system": obj["system"], "status": obj["status"], "note": obj["note"]}
    return records

def parse_csv(path):
    records = {}
    with open(path, encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            records[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}
    return records

def parse_yaml(path):
    records = {}
    cur = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip("\n")
            m = re.match(r'- case: (provider-s03-t04-\d{6})', line)
            if m:
                if cur.get("case"):
                    records[cur["case"]] = {"system": cur["system"], "status": cur["status"], "note": cur["note"]}
                cur = {"case": m.group(1)}
                continue
            m = re.match(r'  system: ([\w-]+)', line)
            if m:
                cur["system"] = m.group(1)
                continue
            m = re.match(r'  status: ([\w-]+)', line)
            if m:
                cur["status"] = m.group(1)
                continue
            m = re.match(r'  note: "(.*)"', line)
            if m:
                cur["note"] = m.group(1)
                continue
        if cur.get("case"):
            records[cur["case"]] = {"system": cur["system"], "status": cur["status"], "note": cur["note"]}
    return records

md = parse_md("provider-s03-t04-evidence-01.md")
jl = parse_jsonl("provider-s03-t04-evidence-02.jsonl")
cs = parse_csv("provider-s03-t04-evidence-03.csv")
ya = parse_yaml("provider-s03-t04-evidence-04.yaml")

print("counts: md=%d jsonl=%d csv=%d yaml=%d" % (len(md), len(jl), len(cs), len(ya)))

sources = {"md": md, "jsonl": jl, "csv": cs, "yaml": ya}
all_cases = sorted(set(md) | set(jl) | set(cs) | set(ya))

mismatches = []
for case in all_cases:
    present = {name: recs.get(case) for name, recs in sources.items() if case in recs}
    if len(present) < 2:
        continue
    values = list(present.values())
    first = values[0]
    for name, rec in present.items():
        if rec != first:
            mismatches.append((case, present))
            break

print("total mismatches across sources for shared cases:", len(mismatches))
for case, present in mismatches:
    print(case, present)
