"""Loopback-only HTTP routes for the recovery flow.

Exposes ``POST /recovery/start``, ``POST /recovery/complete``, and the
bearer-token authenticated ``POST /recovery/notifications/retry``,
``POST /mailbox/migration/preview``, ``POST /mailbox/migration/apply``,
``POST /mailbox/migration/status``, ``POST /mailbox/migration/recover``, and
``POST /mailbox/delivery-history``. Request bodies are read up to a fixed
byte cap before being parsed, so a caller cannot force the process to
buffer an unbounded body.
"""
from __future__ import annotations

import hmac
import json
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import Optional

from .errors import AccountServiceError, ConflictError, NotFoundError, ValidationError
from .service import AccountService
from .validation import MAX_REQUEST_BODY_BYTES

_STATUS_FOR_ERROR = {
    ValidationError: 400,
    NotFoundError: 404,
    ConflictError: 409,
}


def _status_for(exc: AccountServiceError) -> int:
    return _STATUS_FOR_ERROR.get(type(exc), 400)


def _make_handler(service: AccountService, bearer_token: str) -> type:
    class Handler(BaseHTTPRequestHandler):
        server_version = "accountsvc/0.1"

        def log_message(self, format: str, *args: object) -> None:  # noqa: A002 - stdlib signature
            pass  # keep test/CLI output free of per-request access logs

        def _read_json_body(self) -> Optional[dict]:
            length_header = self.headers.get("Content-Length")
            if length_header is None:
                self._send_json(400, {"error": "Content-Length header is required"})
                return None
            try:
                length = int(length_header)
            except ValueError:
                self._send_json(400, {"error": "Content-Length must be an integer"})
                return None
            if length < 0 or length > MAX_REQUEST_BODY_BYTES:
                self._send_json(413, {"error": "request body too large"})
                return None
            raw = self.rfile.read(length) if length else b""
            if not raw:
                return {}
            try:
                parsed = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                self._send_json(400, {"error": "request body must be valid JSON"})
                return None
            if not isinstance(parsed, dict):
                self._send_json(400, {"error": "request body must be a JSON object"})
                return None
            return parsed

        def _send_json(self, status: int, payload: dict) -> None:
            body = json.dumps(payload).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

